changeSet.sql:
-- user_package: user_id → user_in (PINFL'dan backfill, faqat user_id bor bo'lsa)
ALTER TABLE "user".user_package ADD COLUMN IF NOT EXISTS user_in TEXT;
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'user' AND table_name = 'user_package'
                 AND column_name = 'user_id') THEN
        UPDATE "user".user_package up SET user_in = u.pinfl
            FROM "user"."user" u
            WHERE u.id = up.user_id AND up.user_in IS NULL;
    END IF;
END $$;
DROP INDEX IF EXISTS "user".user_idx_user_package_user;
ALTER TABLE "user".user_package DROP COLUMN IF EXISTS user_id;
CREATE INDEX IF NOT EXISTS user_idx_user_package_in
    ON "user".user_package (user_in);

-- purchases: user_id → user_in + promo
ALTER TABLE "user".purchases ADD COLUMN IF NOT EXISTS user_in TEXT;
ALTER TABLE "user".purchases ADD COLUMN IF NOT EXISTS promo    TEXT;
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'user' AND table_name = 'purchases'
                 AND column_name = 'user_id') THEN
        UPDATE "user".purchases p SET user_in = u.pinfl
            FROM "user"."user" u
            WHERE u.id = p.user_id AND p.user_in IS NULL;
    END IF;
END $$;
DROP INDEX IF EXISTS "user".user_idx_purchases_user;
ALTER TABLE "user".purchases DROP COLUMN IF EXISTS user_id;
CREATE INDEX IF NOT EXISTS user_idx_purchases_in
    ON "user".purchases (user_in);

-- purchase_history — butunlay o'chirildi (bog'liq obyektlar bilan)
DROP TABLE IF EXISTS "user".purchase_history CASCADE;
